def choose_move(observation):
    # Defensive extraction of position and other relevant info
    own_pos = observation.get('player', {}).get('position', (0, 0))
    own_x, own_y = own_pos
    grid = observation.get('grid', [])
    # Default to no movement
    dx, dy = 0, 0

    # Helper function to check for resource or enemy at position
    def is_enemy_at(x, y):
        return any(enemy.get('position') == (x, y) for enemy in observation.get('enemies', []))
    def is_resource_at(x, y):
        return any(resource.get('position') == (x, y) for resource in observation.get('resources', []))
    def within_bounds(x, y):
        return 0 <= y < len(grid) and 0 <= x < len(grid[0]) if grid else False

    # Resource collection: Move towards nearest resource
    resources = observation.get('resources', [])
    if resources:
        # Compute Manhattan distance
        def dist(r):
            rx, ry = r.get('position', (0, 0))
            return abs(rx - own_x) + abs(ry - own_y)
        nearest_res = min(resources, key=dist)
        rx, ry = nearest_res.get('position', (own_x, own_y))
        dx, dy = 0, 0
        if rx > own_x:
            dx = 1
        elif rx < own_x:
            dx = -1
        elif ry > own_y:
            dy = 1
        elif ry < own_y:
            dy = -1
        return [dx, dy]

    # Pursuit/Evasion: Move to avoid or chase enemies
    enemies = observation.get('enemies', [])
    if enemies:
        # For simplicity, evade the closest enemy
        def dist_en(e):
            ex, ey = e.get('position', (0,0))
            return abs(ex - own_x) + abs(ey - own_y)
        nearest_e = min(enemies, key=dist_en)
        ex, ey = nearest_e.get('position', (own_x, own_y))
        dx, dy = 0, 0
        # Move away if enemy is close
        if abs(ex - own_x) + abs(ey - own_y) <= 3:
            if ex > own_x:
                dx = -1
            elif ex < own_x:
                dx = 1
            if ey > own_y:
                dy = -1
            elif ey < own_y:
                dy = 1
        else:
            # Otherwise, move randomly or towards resource if available
            pass
        return [dx, dy]

    # Territory control: Move towards center
    grid_width = len(grid[0]) if grid else 0
    grid_height = len(grid)
    center_x = grid_width // 2
    center_y = grid_height // 2

    dx, dy = 0, 0
    if own_x < center_x:
        dx = 1
    elif own_x > center_x:
        dx = -1
    if own_y < center_y:
        dy = 1
    elif own_y > center_y:
        dy = -1

    return [dx, dy]

